def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    recent_start = max(0, n - 8)
    recent_opp_d = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
        if i >= recent_start and history[i][1] == 'D':
            recent_opp_d += 1

    opp_d = n - opp_c

    if opp_d == 0:
        if n == 70:
            return 'D'
        if n == 71 or n == 72:
            return 'C'
        if n >= 73:
            return 'D'
        return 'C'

    if opp_c == 0:
        return 'D'

    opp_rate = (opp_c + 1.0) / (n + 2.0)
    if opp_rate <= 0.30:
        return 'D'

    opp_streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_streak_d += 1
        i -= 1

    opp_streak_c = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        opp_streak_c += 1
        i -= 1

    if n >= 8 and recent_opp_d >= 5:
        return 'D'

    if n >= 4 and opp_streak_d >= 3:
        return 'D'

    my_last, opp_last = history[-1]

    if opp_last == 'D':
        if my_last == 'C':
            if n >= 2 and history[-2][0] == 'D' and opp_streak_d <= 2 and recent_opp_d <= 2 and opp_rate >= 0.60:
                return 'C'
            return 'D'
        else:
            if opp_rate >= 0.60 and recent_opp_d <= 3:
                return 'C'
            return 'D'

    if my_last == 'D':
        if opp_rate >= 0.85 and opp_streak_c >= 5 and recent_opp_d == 0 and n < 95:
            return 'D'
        return 'C'

    return 'C'
